// =====================================================================
//  Dayus Manroe: BOSS KIT, Foundry v14 (CAT) copy (Script macro, run as GM). Run after
//  "Dayus Manroe: fixes" (v14). Safe to re-run. Generated by tools/court-boss-build (v14 target)
//  from boss-core-v14.js. Same boss as the v13 kit, sized for a lieutenant:
//   - Legendary Actions (3, regained at the start of the turn): Seal (1, spends a seal
//     from the pool), Strike (2), Veil of Lies (2).
//   - Legendary Resistance (3/day) + Blood Price in one prompt on a failed save
//     (Dracula's: Legendary Resistance bleeds floor(spell level / 2) d10).
//   - Invoke Hell options: 1/day each, no shared Invoke Hell use.
//  Seals keep their normal pool (6, back on a short rest); Dracula alone has unlimited seals.
//  v14 differences: on v14 the exported sheet IS the boss (no "(Boss)" copy); Blood Price +
//  Legendary Resistance is Nix Fix's bloodPriceLegendary function macro on the Legendary
//  Resistance item (the same one Dracula's v14 kit uses; Blood Price's own macro steps aside).
//  On an NPC stat block (tool "Make stat block"): native pips, Legendary Actions section.
// =====================================================================
const MOD = 'nix-module';
const F = game.modules.get(MOD)?.api?.illriggerFeatures;
if (!globalThis.cat?.utils) return ui.notifications.error('Dayus Manroe boss kit (v14): CAT is not active.');
if (!F?.refFor?.('bloodPriceLegendary')) return ui.notifications.error('Dayus Manroe boss kit (v14): Nix Fix is too old (no bloodPriceLegendary). Update it and reload.');
const actor = canvas.tokens.controlled[0]?.actor;
if (!actor) return ui.notifications.warn('Dayus Manroe boss kit: no actor.');
const cfg = actor.flags?.[MOD]?.illrigger;
if (!cfg || cfg.engine !== 'cat') return ui.notifications.warn('Dayus Manroe boss kit (v14): apply the Illrigger engine (v14) first.');
if (actor.flags?.[MOD]?.court?.key !== 'dayus') return ui.notifications.warn('Dayus Manroe boss kit (v14): apply "Dayus Manroe: fixes" to ' + actor.name + ' first.');
const report = [];
const ident = d => d?.flags?.['chris-premades']?.info?.identifier ?? d?.flags?.[MOD]?.identifier ?? d?.flags?.cat?.identifier;
const find = (id, re) => actor.items.find(i => id && ident(i) === id) ?? actor.items.find(i => re.test(i.name));
const act = (id, type, data) => ({_id: id, type, ...data});
// Create the item, or update the one already there (type left out of updates).
async function ensureItem(data, match) {
    const it = actor.items.find(match);
    if (it) { const {type, ...upd} = data; await it.update(upd); return actor.items.get(it.id); }
    const [made] = await actor.createEmbeddedDocuments('Item', [data]);
    return made;
}
// Function-macro references (flags.cat.macros), merged without duplicates.
function withRef(doc, identifier) {
    const ref = F.refFor(identifier);
    const cur = foundry.utils.deepClone(doc?.flags?.cat?.macros ?? {});
    for (const [type, list] of Object.entries(ref)) cur[type] = (cur[type] ?? []).filter(r => !(r.source === MOD && r.identifier === identifier)).concat(list);
    return cur;
}

// ---- Legendary Actions (3) -----------------------------------------------------------------
function legendary(signature, sigText, preferRanged) {
    const weapons = actor.items.filter(i => i.type === 'weapon' && i.system.equipped && i.system.activities?.some(a => a.type === 'attack'));
    const ranged = w => /R$/.test(w.system.type?.value ?? '') || w.system.activities.some(a => a.type === 'attack' && a.attack?.type?.value === 'ranged');
    const real = weapons.filter(w => w.system.type?.value !== 'natural' && !/^unarmed strike/i.test(w.name));
    const pool = real.length ? real : weapons;
    const strike = (preferRanged ? pool.find(ranged) : pool.find(w => !ranged(w))) ?? pool[0] ?? null;
    return {strike, data: {
        name: 'Legendary Actions', type: 'feat', img: 'icons/magic/unholy/hand-claw-glow-orange.webp',
        system: {
            description: {value: '<p>' + actor.name + ' can take 3 Legendary Actions, one at a time, immediately after another creature\'s turn, and regains them at the start of their turn.</p>'
                + '<ul><li><b>Seal (1).</b> Place a Baleful Interdict seal on a creature within ' + cfg.range + ' ft (spends a seal).</li>'
                + '<li><b>Strike (2).</b> One attack with ' + (strike ? strike.name : 'a weapon') + '.</li>' + sigText + '</ul>'},
            type: {value: 'monster', subtype: ''},
            uses: {max: '3', spent: 0, recovery: [{period: 'turnStart', type: 'recoverAll'}]},
            activities: Object.assign({
                nixLegendSeal000: act('nixLegendSeal000', 'utility', {name: 'Seal (1)', activation: {type: 'special', value: 1}, range: {value: String(cfg.range), units: 'ft'},
                    target: {affects: {count: '1', type: 'creature'}}, consumption: {targets: [{type: 'itemUses', target: '', value: '1'}]}, flags: {[MOD]: {boss: 'seal'}}}),
                nixLegendStrike0: act('nixLegendStrike0', 'utility', {name: 'Strike (2)', activation: {type: 'special', value: 2}, range: {units: 'self'},
                    target: {affects: {count: '1', type: 'creature'}}, consumption: {targets: [{type: 'itemUses', target: '', value: '2'}]}, flags: {[MOD]: {boss: 'strike'}}})
            }, signature)
        },
        flags: {[MOD]: {legendary: true}}
    }};
}
async function installLegendary(signature, sigText, preferRanged) {
    const {strike, data} = legendary(signature, sigText, preferRanged);
    const la = await ensureItem(data, i => i.flags?.[MOD]?.legendary || /^legendary actions$/i.test(i.name));
    report.push('Legendary Actions: 3, back at the start of the turn. Seal (1, spends a seal), Strike (2: ' + (strike?.name ?? '<b>no equipped weapon</b>') + '), ' + sigText.replace(/<[^>]+>/g, '').replace(/\.\s.*$/, '') + '.');
    // Boss flags (shared with Dracula's runtime).
    await actor.update({['flags.' + MOD + '.boss']: {version: 1, phase2: false, ascendedThisRest: false, legendaryItem: la.id, lairScenes: [],
        legendaryBase: 3, legendaryLair: 3, regen: false, paidSeals: true, strikeItem: strike?.id ?? null, radiantTaken: 0}});
    return la;
}

// ---- Legendary Resistance + Blood Price ----------------------------------------------------
async function installResistance() {
    const lrMatch = i => i.flags?.[MOD]?.legendaryResistance;
    const lrOld = actor.items.find(lrMatch);
    const npcSpent = actor.type === 'npc' && actor.system.resources?.legres?.max ? actor.system.resources.legres.spent : null;
    await ensureItem({
        name: 'Legendary Resistance (Blood Price)', type: 'feat', img: 'icons/magic/life/heart-cross-strong-flame-purple-orange.webp',
        system: {
            description: {value: '<p>3/day. When ' + actor.name + ' fails a saving throw they can succeed instead. Against a spell they bleed d10s equal to half the spell\'s level, rounded down '
                + '(1st: none, 2nd-3rd: 1d10, 4th-5th: 2d10, 6th-7th: 3d10, 8th-9th: 4d10). No spell level: no bleed. Asked together with Blood Price on the same prompt.</p>'},
            type: {value: 'monster', subtype: ''},
            uses: {max: '3', spent: npcSpent ?? lrOld?.system.uses?.spent ?? 0, recovery: [{period: 'lr', type: 'recoverAll'}]}
        },
        flags: {[MOD]: {legendaryResistance: true, bloodPriceLegendary: true, identifier: 'legendaryResistanceBloodPrice'}, cat: {macros: withRef(lrOld, 'bloodPriceLegendary')}}
    }, lrMatch);
    const bp = find('bloodPrice', /^blood price/i);
    report.push('Blood Price + Legendary Resistance (3/day): one prompt on a failed save ('
        + (bp ? 'spend a Hit Die / ' : '') + 'succeed and bleed / accept).'
        + (bp ? '' : ' <b>No Blood Price on the sheet</b>: the Hit Die option is left out.'));
}

// ---- Invoke Hell options: 1/day each -------------------------------------------------------
async function invokeHellDaily() {
    const done = [];
    for (const item of actor.items.filter(i => /^invoke hell/i.test(i.name) && i.system.activities?.size)) {
        const upd = {};
        for (const a of item.system.activities) {
            upd['system.activities.' + a.id + '.uses'] = {max: '1', spent: a.uses?.max === '1' ? (a.uses.spent ?? 0) : 0, recovery: [{period: 'lr', type: 'recoverAll'}]};
            upd['system.activities.' + a.id + '.consumption.targets'] = [{type: 'activityUses', target: '', value: '1'}];
            done.push(a.name === item.name ? item.name : item.name + ': ' + a.name);
        }
        await item.update(upd);
    }
    report.push(done.length ? 'Invoke Hell, 1/day each: ' + done.join(', ') + '.' : 'Invoke Hell: no options with activities found.');
}

await installLegendary({
    nixLegendVeil000: act('nixLegendVeil000', 'utility', {name: 'Veil of Lies (2)', activation: {type: 'special', value: 2}, range: {units: 'self'},
        consumption: {targets: [{type: 'itemUses', target: '', value: '2'}]}, flags: {[MOD]: {court: 'veil'}}})
}, "<li><b>Veil of Lies (2).</b> Spend a seal and turn invisible until he attacks or casts a spell (10 minutes).</li>", true);
await installResistance();
await invokeHellDaily();
// NPC stat block (tool "Make stat block"): native pips, Legendary Actions section.
if (actor.type === 'npc') {
    const sb = game.modules.get(MOD)?.api?.statBlock;
    if (sb?.npcLegendary) report.push(...await sb.npcLegendary(actor));
    else report.push('<b>NPC:</b> Nix Fix\'s stat block runtime isn\'t running, so the stat block layout was skipped.');
}
if (!game.modules.get(MOD)?.api?.boss) report.push('<b>Nix Fix\'s boss runtime isn\'t running</b> (Legendary Actions need it): update Nix Fix and reload.');
await ChatMessage.create({whisper: [game.user.id], content: '<b>Nix Fix: ' + actor.name + ' boss kit (v14)</b><ul><li>' + report.join('</li><li>') + '</li></ul>'});
